create type public.app_role as enum ('student','tutor','admin','owner');
create type public.exercise_type as enum ('step-sequencer','piano-roll','arrangement','mixer-eq','compression','signal-flow','automation','comparison','mastering-export');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null default '',role app_role not null default 'student',created_at timestamptz not null default now());
create table public.lab_exercises(id text primary key,title text not null,type exercise_type not null,instructions text not null,assets jsonb not null default '[]',initial_state jsonb not null default '{}',rules jsonb not null default '[]',submission_requirements jsonb not null default '{}',created_at timestamptz not null default now());
create table public.lab_submissions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles,exercise_id text not null references public.lab_exercises,attempt_number int not null default 1,project_state_json jsonb not null,rendered_audio_key text,reflection text,automatic_score numeric,tutor_score numeric,feedback text,submitted_at timestamptz not null default now(),graded_at timestamptz,unique(student_id,exercise_id,attempt_number));
create table public.daw_assignment_assets(id uuid primary key default gen_random_uuid(),name text not null,asset_type text not null,storage_key text not null,created_at timestamptz not null default now());
create table public.audio_analysis_jobs(id uuid primary key default gen_random_uuid(),student_id uuid references public.profiles,source_audio_key text not null,status text not null default 'queued',analysis_json jsonb,result_waveform_key text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.tutor_timestamp_comments(id uuid primary key default gen_random_uuid(),submission_id uuid references public.lab_submissions,analysis_job_id uuid references public.audio_analysis_jobs,tutor_id uuid references public.profiles,timestamp_ms int not null,body text not null,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.lab_exercises enable row level security;alter table public.lab_submissions enable row level security;alter table public.daw_assignment_assets enable row level security;alter table public.audio_analysis_jobs enable row level security;alter table public.tutor_timestamp_comments enable row level security;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in ('tutor','admin','owner'))$$;
create policy "profiles self or staff" on public.profiles for select using(id=auth.uid() or public.is_staff());
create policy "exercises readable" on public.lab_exercises for select using(true);
create policy "submissions own or staff" on public.lab_submissions for select using(student_id=auth.uid() or public.is_staff());
create policy "submissions own insert" on public.lab_submissions for insert with check(student_id=auth.uid());
create policy "audio jobs own or staff" on public.audio_analysis_jobs for select using(student_id=auth.uid() or public.is_staff());
create policy "comments participant" on public.tutor_timestamp_comments for select using(public.is_staff() or exists(select 1 from lab_submissions s where s.id=submission_id and s.student_id=auth.uid()));
